CREATE TEMP TABLE s503c_cards (id bigint, s_ed text, s_book text, src_ch int, src_vn int, src_text text, t_ed text, tgt_book text, tgt_ch int, tgt_vn int, old_note text, new_note text, thread_id bigint, old_mnote text, new_mnote text) ON COMMIT DROP;
INSERT INTO s503c_cards VALUES
(5007,'canon','mark',2,5,$n$When Yahusha (Jesus) saw their faith, he said unto the sick of the palsy, Son, your sins be forgiven you.$n$,'canon','daniel',7,13,$n$thread:son-of-adam-as-judge-and-ladder | *Son, thy sins be forgiven thee.* The Son of Adam forgiving sins on earth is the Daniyel (Daniel) 7:13-14 enthronement-authority exercised in the room — the dominion-and-glory-and-kingdom given to the *like the Son of Adam* coming-with-the-clouds.$n$,$n$Daniel 7:13 — *I saw in the night visions, and, behold, one like the Son of Adam came with the clouds of heaven, and came to the Ancient of days, and they brought him near before him.* *When Yahusha (Jesus) saw their faith, he said unto the sick of the palsy, Son, your sins be forgiven you.* (Mark 2:5) Yahusha (Jesus) says *Son, thy sins be forgiven thee* to a man on a bed, and the room hears it as too much. Daniel saw *one like the Son of Adam* brought near before the Ancient of days, and on Daniel's page it stays *like*. The one forgiving on earth is the one Daniel saw given the kingdom above.$n$,692,$n$*Son, thy sins be forgiven thee.* The Son of Adam forgiving sins on earth is the Daniyel (Daniel) 7:13-14 enthronement-authority exercised in the room — the dominion-and-glory-and-kingdom given to the *like the Son of Adam* coming-with-the-clouds.$n$,$n$Daniel 7:13 — *behold, one like the Son of Adam came with the clouds of heaven.* Daniel sees one like the Son of Adam brought near the Ancient of days, and the same name stands in the room forgiving the man on the bed.$n$),
(5009,'canon','mark',2,10,$n$But that you may know that the Son of Adam has power on earth to forgive sins, (he says to the sick of the palsy,)$n$,'canon','daniel',7,13,$n$thread:son-of-adam-as-judge-and-ladder | *The Son of Adam hath power on earth to forgive sins.* The Daniyel (Daniel) 7 title is named explicitly — the one to whom the dominion was given, exercising that dominion in the room. The *on earth* localizes the heavenly enthronement of Daniyel 7:14 into the present moment.$n$,$n$Daniel 7:13 — *I saw in the night visions, and, behold, one like the Son of Adam came with the clouds of heaven, and came to the Ancient of days, and they brought him near before him.* *But that you may know that the Son of Adam has power on earth to forgive sins, (he says to the sick of the palsy,)* (Mark 2:10) Here Yahusha (Jesus) says the name outright: *the Son of Adam hath power on earth*. Daniel saw *one like the Son of Adam* come to the Ancient of days, and Daniel keeps the *like*. What Daniel sees given from the throne is what is being used on earth, in front of a man who could not walk.$n$,692,$n$*The Son of Adam hath power on earth to forgive sins.* The Daniyel (Daniel) 7 title is named explicitly — the one to whom the dominion was given, exercising that dominion in the room. The *on earth* localizes the heavenly enthronement of Daniyel 7:14 into the present moment.$n$,$n$Daniel 7:13 — *and came to the Ancient of days, and they brought him near before him.* The one brought near the Ancient of days in Daniel is the Son of Adam who here forgives sins on earth.$n$),
(5021,'canon','mark',2,28,$n$Therefore the Son of Adam is the Lord also of the sabbath.$n$,'canon','daniel',7,13,$n$thread:son-of-adam-as-judge-and-ladder | *Therefore the Son of Adam is Yahuah (Lord) also of the sabbath.* The Daniyel (Daniel) 7 title carrying the *Yahuah even of the sabbath* claim — the Formed one naming himself as the one who gave the day at Bereshit (Genesis) 2 and at Sinai.$n$,$n$Daniel 7:13 — *I saw in the night visions, and, behold, one like the Son of Adam came with the clouds of heaven, and came to the Ancient of days, and they brought him near before him.* *Therefore the Son of Adam is the Lord also of the sabbath.* (Mark 2:28) Daniel saw *one like the Son of Adam* come to the Ancient of days, and Daniel keeps his *like*. Yahusha (Jesus) says the Son of Adam is master *also of the sabbath*. That is the one who made the day saying whose it is. The sabbath is not put away. It stands, with its owner standing in front of it.$n$,692,$n$*Therefore the Son of Adam is Yahuah (Lord) also of the sabbath.* The Daniyel (Daniel) 7 title carrying the *Yahuah even of the sabbath* claim — the Formed one naming himself as the one who gave the day at Bereshit (Genesis) 2 and at Sinai.$n$,$n$Daniel 7:13 — *one like the Son of Adam came with the clouds of heaven, and came to the Ancient of days.* The one Daniel saw come before the Ancient of days is the one who says the sabbath is his, and he says it to keep the day.$n$),
(5139,'canon','mark',8,31,$n$And he began to teach them, that the Son of Adam must suffer many things, and be rejected of the elders, and of the chief priests, and scribes, and be killed, and after three days rise again.$n$,'canon','genesis',3,15,$n$thread:son-of-adam-as-judge-and-ladder | *The Son of Adam must suffer many things... and be killed, and after three days rise again.* The seed of the woman that bruises the serpent's head (Bereshit/Genesis 3:15) must first be bruised.$n$,$n$Genesis 3:15 — *And I will put enmity between thee and the woman, and between thy seed and her seed; it shall bruise thy head, and thou shalt bruise his heel.* *And he began to teach them, that the Son of Adam must suffer many things, and be rejected of the elders, and of the chief priests, and scribes, and be killed, and after three days rise again.* (Mark 8:31) The woman's seed is the one who bruises the serpent's head, and the heel is where he is bruised. Yahusha (Jesus) says the Son of Adam *must suffer many things* and be killed, and then rise. The heel comes first, and the head after.$n$,692,$n$*The Son of Adam must suffer many things... and be killed, and after three days rise again.* The seed of the woman that bruises the serpent's head (Bereshit/Genesis 3:15) must first be bruised.$n$,$n$Genesis 3:15 — *it shall bruise thy head, and thou shalt bruise his heel.* The seed of the woman crushes the serpent's head and is bruised in the heel, which is the suffering the Son of Adam says he must go through.$n$),
(5141,'canon','mark',8,31,$n$And he began to teach them, that the Son of Adam must suffer many things, and be rejected of the elders, and of the chief priests, and scribes, and be killed, and after three days rise again.$n$,'canon','psalms',8,4,$n$thread:son-of-adam-as-judge-and-ladder | *What is man, that thou art mindful of him? and the son of adam, that thou visitest him?* (Tehillim/Psalm 8:4).$n$,$n$Psalm 8:4 — *What is man, that thou art mindful of him? and the son of Adam, that thou visitest him?* *And he began to teach them, that the Son of Adam must suffer many things, and be rejected of the elders, and of the chief priests, and scribes, and be killed, and after three days rise again.* (Mark 8:31) The psalm asks what a son of Adam is that he should be visited at all. Yahusha (Jesus) answers with a hard word: the Son of Adam *must suffer many things*, and be rejected by the elders and priests. The psalm that asks it goes on to give him dominion, so the road runs through rejection to that.$n$,692,$n$*What is man, that thou art mindful of him? and the son of adam, that thou visitest him?* (Tehillim/Psalm 8:4).$n$,$n$Psalm 8:4 — *and the son of Adam, that thou visitest him.* The psalm's son of Adam, visited from above, is the one who is rejected and killed and then rises after three days.$n$),
(5140,'canon','mark',8,31,$n$And he began to teach them, that the Son of Adam must suffer many things, and be rejected of the elders, and of the chief priests, and scribes, and be killed, and after three days rise again.$n$,'canon','daniel',7,13,$n$thread:son-of-adam-as-judge-and-ladder | The Daniyel (Daniel) 7:13-14 dominion-architecture carries the Son of Adam through the suffering and into the resurrection.$n$,$n$Daniel 7:13 — *I saw in the night visions, and, behold, one like the Son of Adam came with the clouds of heaven, and came to the Ancient of days, and they brought him near before him.* *And he began to teach them, that the Son of Adam must suffer many things, and be rejected of the elders, and of the chief priests, and scribes, and be killed, and after three days rise again.* (Mark 8:31) Yahusha (Jesus) says the Son of Adam will be rejected, killed, and rise after three days. Daniel saw *one like the Son of Adam* brought near before the Ancient of days. Suffering and coming near belong to one person. Daniel keeps his *like*, and Yahusha (Jesus) speaks the name straight.$n$,692,$n$The Daniyel (Daniel) 7:13-14 dominion-architecture carries the Son of Adam through the suffering and into the resurrection.$n$,$n$Daniel 7:13 — *and came to the Ancient of days, and they brought him near before him.* The one who is brought near the Ancient of days in Daniel is the one who must first suffer and be killed.$n$),
(5154,'canon','mark',8,38,$n$Whosoever therefore shall be ashamed of me and of my words in this adulterous and sinful generation; of him also shall the Son of Adam be ashamed, when he comes in the glory of his Father with the holy angels.$n$,'canon','matthew',10,33,$n$thread:son-of-adam-as-judge-and-ladder | *Of him also shall the Son of Adam be ashamed, when he cometh in the glory of his Father.* Direct title-assignment (no kaph) of the post-resurrection return-in-glory.$n$,$n$Matthew 10:33 — *But whosoever shall deny me before men, him will I also deny before my Father which is in heaven.* *Whosoever therefore shall be ashamed of me and of my words in this adulterous and sinful generation; of him also shall the Son of Adam be ashamed, when he comes in the glory of his Father with the holy angels.* (Mark 8:38) Whoever denies Yahusha (Jesus) before men is denied before the Father in heaven. Mark says the Son of Adam will be ashamed of that person *in the glory of his Father*. The judgment is given to the Son of Adam, and it is given before the Father, who is not set aside.$n$,692,$n$*Of him also shall the Son of Adam be ashamed, when he cometh in the glory of his Father.* Direct title-assignment (no kaph) of the post-resurrection return-in-glory.$n$,$n$Matthew 10:33 — *him will I also deny before my Father which is in heaven.* Denying him before men is answered by his denying that person before his Father, which is the Son of Adam acting as judge in the Father's presence.$n$),
(5155,'canon','mark',8,38,$n$Whosoever therefore shall be ashamed of me and of my words in this adulterous and sinful generation; of him also shall the Son of Adam be ashamed, when he comes in the glory of his Father with the holy angels.$n$,'canon','luke',12,9,$n$thread:son-of-adam-as-judge-and-ladder | The Lukan parallel of the ashamed-of-me / ashamed-of-him saying.$n$,$n$Luke 12:9 — *But he that denieth me before men shall be denied before the angels of Elohim (God).* *Whosoever therefore shall be ashamed of me and of my words in this adulterous and sinful generation; of him also shall the Son of Adam be ashamed, when he comes in the glory of his Father with the holy angels.* (Mark 8:38) Luke has the same saying with the angels in view. The one who denies Yahusha (Jesus) before men *shall be denied*, and Mark's Son of Adam comes *with the holy angels*. Both verses stand at one judgment, and the name Son of Adam is the one who confesses or denies there.$n$,692,$n$The Lukan parallel of the ashamed-of-me / ashamed-of-him saying.$n$,$n$Luke 12:9 — *he that denieth me before men shall be denied before the angels.* The denial before men is answered before the angels of Elohim (God), the same company that comes with the Son of Adam in his Father's glory.$n$),
(5156,'canon','mark',8,38,$n$Whosoever therefore shall be ashamed of me and of my words in this adulterous and sinful generation; of him also shall the Son of Adam be ashamed, when he comes in the glory of his Father with the holy angels.$n$,'canon','2-timothy',2,12,$n$thread:son-of-adam-as-judge-and-ladder | *If we deny him, he also will deny us* (2 Timothy 2:12).$n$,$n$2 Timothy 2:12 — *If we suffer, we shall also reign with him: if we deny him, he also will deny us:* *Whosoever therefore shall be ashamed of me and of my words in this adulterous and sinful generation; of him also shall the Son of Adam be ashamed, when he comes in the glory of his Father with the holy angels.* (Mark 8:38) Paul writes the same saying down for those who suffer. They will reign with him, and whoever denies him will be denied by him. It is the weight Yahusha (Jesus) puts on the Son of Adam being ashamed. Judgment follows what a person did with him and his words.$n$,692,$n$*If we deny him, he also will deny us* (2 Timothy 2:12).$n$,$n$2 Timothy 2:12 — *if we deny him, he also will deny us.* Denying him is met with his denying, which is the same judgment given to the Son of Adam in Mark.$n$),
(5180,'canon','mark',9,29,$n$And he said unto them, This kind can come forth by nothing, but by prayer and fasting.$n$,'canon','daniel',7,9,$n$thread:son-of-adam-as-judge-and-ladder | *This kind can come forth by nothing, but by prayer and fasting* — the authority of the Son of Adam is exercised through the posture of dependence on the Father (Daniyel/Daniel 7:9, 13-14).$n$,$n$Daniel 7:9 — *I beheld till the thrones were cast down, and the Ancient of days did sit, whose garment was white as snow, and the hair of his head like the pure wool: his throne was like the fiery flame, and his wheels as burning fire.* *And he said unto them, This kind can come forth by nothing, but by prayer and fasting.* (Mark 9:29) Daniel sees the Ancient of days seated, with a throne *like the fiery flame*. The one brought near him receives; he does not seize. Yahusha (Jesus) sends his men to prayer and fasting, the posture of one who has a Father and asks. The power in the room comes from the one on that throne.$n$,692,$n$*This kind can come forth by nothing, but by prayer and fasting* — the authority of the Son of Adam is exercised through the posture of dependence on the Father (Daniyel/Daniel 7:9, 13-14).$n$,$n$Daniel 7:9 — *the Ancient of days did sit, whose garment was white as snow.* The Ancient of days sits on the throne the Son of Adam is brought before, and the power he uses comes from there through prayer.$n$),
(5184,'canon','mark',9,31,$n$For he taught his disciples, and said unto them, The Son of Adam is delivered into the hands of men, and they shall kill him; and after that he is killed, he shall rise the third day.$n$,'canon','isaiah',53,5,$n$thread:son-of-adam-as-judge-and-ladder | *He was wounded for our transgressions, he was bruised for our iniquities* (Yeshayahu/Isaiah 53:5-8).$n$,$n$Isaiah 53:5 — *But he was wounded for our transgressions, he was bruised for our iniquities: the chastisement of our peace was upon him; and with his stripes we are healed.* *For he taught his disciples, and said unto them, The Son of Adam is delivered into the hands of men, and they shall kill him; and after that he is killed, he shall rise the third day.* (Mark 9:31) The Son of Adam is given into men's hands and killed, and Isaiah had already said why. The servant was *wounded for our transgressions*, bruised for iniquities, and the stripes heal. The one who rises the third day is the one who carried that.$n$,692,$n$*He was wounded for our transgressions, he was bruised for our iniquities* (Yeshayahu/Isaiah 53:5-8).$n$,$n$Isaiah 53:5 — *he was wounded for our transgressions, he was bruised for our iniquities.* Isaiah's wounded and bruised servant is the Son of Adam delivered to men and killed.$n$),
(5183,'canon','mark',9,31,$n$For he taught his disciples, and said unto them, The Son of Adam is delivered into the hands of men, and they shall kill him; and after that he is killed, he shall rise the third day.$n$,'canon','daniel',7,13,$n$thread:son-of-adam-as-judge-and-ladder | The Son of Adam who bears the everlasting dominion is the same who lays his life down. The lineage-name carries both the throne and the tree.$n$,$n$Daniel 7:13 — *I saw in the night visions, and, behold, one like the Son of Adam came with the clouds of heaven, and came to the Ancient of days, and they brought him near before him.* *For he taught his disciples, and said unto them, The Son of Adam is delivered into the hands of men, and they shall kill him; and after that he is killed, he shall rise the third day.* (Mark 9:31) In Daniel the one brought near before the Ancient of days, *like the Son of Adam*, is given an everlasting kingdom. Yahusha (Jesus) says the Son of Adam is delivered up, killed, and rises the third day. The throne and the death sit in one name, and Daniel's word stays *like*.$n$,692,$n$The Son of Adam who bears the everlasting dominion is the same who lays his life down. The lineage-name carries both the throne and the tree.$n$,$n$Daniel 7:13 — *I saw in the night visions, and, behold, one like the Son of Adam came with the clouds of heaven.* The Son of Adam who is given the everlasting dominion in Daniel is the same who lays down his life.$n$),
(5212,'canon','mark',10,45,$n$For even the Son of Adam came not to be ministered unto, but to minister, and to give his life a ransom for many.$n$,'canon','isaiah',53,11,$n$thread:son-of-adam-as-judge-and-ladder | *By his knowledge shall my righteous servant justify many; for he shall bear their iniquities.*$n$,$n$Isaiah 53:11 — *He shall see of the travail of his soul, and shall be satisfied: by his knowledge shall my righteous servant justify many; for he shall bear their iniquities.* *For even the Son of Adam came not to be ministered unto, but to minister, and to give his life a ransom for many.* (Mark 10:45) The ransom for many is Isaiah's servant, who justifies *many* and *shall bear their iniquities*. Yahusha (Jesus) says the Son of Adam came to serve and give his life as a ransom for many. It is the same many and the same bearing, and the serving is done before the being served.$n$,692,$n$*By his knowledge shall my righteous servant justify many; for he shall bear their iniquities.*$n$,$n$Isaiah 53:11 — *by his knowledge shall my righteous servant justify many.* Isaiah's righteous servant who justifies many by bearing their iniquities is the Son of Adam giving his life as a ransom.$n$),
(5213,'canon','mark',10,45,$n$For even the Son of Adam came not to be ministered unto, but to minister, and to give his life a ransom for many.$n$,'canon','daniel',7,13,$n$thread:son-of-adam-as-judge-and-ladder | The Daniyel (Daniel) 7:13-14 dominion-architecture carried into the ransom-saying.$n$,$n$Daniel 7:13 — *I saw in the night visions, and, behold, one like the Son of Adam came with the clouds of heaven, and came to the Ancient of days, and they brought him near before him.* *For even the Son of Adam came not to be ministered unto, but to minister, and to give his life a ransom for many.* (Mark 10:45) The one Daniel saw *like the Son of Adam* come to the Ancient of days is the one who says he came *not to be ministered unto, but to minister*. The dominion Daniel saw given comes by way of a life laid down as a ransom. Daniel keeps his *like*, and Yahusha (Jesus) speaks the name.$n$,692,$n$The Daniyel (Daniel) 7:13-14 dominion-architecture carried into the ransom-saying.$n$,$n$Daniel 7:13 — *behold, one like the Son of Adam came with the clouds of heaven.* The one Daniel saw coming with the clouds of heaven is the Son of Adam who gives his life as a ransom for many.$n$),
(6972,'canon','luke',2,49,$n$And he said unto them, How is it that you sought me? wist you not that I must be about my Father’s business?$n$,'canon','john',2,16,$n$thread:son-of-adam-as-judge-and-ladder | *Wist ye not that I must be about my Father's business?* The twelve-year-old in the temple names the Father-Son relation that the Yochanan (John) 2 cleansing of the temple names — *make not my Father's house an house of merchandise.* The Formed-Son's first recorded words in Luke are the same Father-naming the Yochanan gospel returns to throughout.$n$,$n$John 2:16 — *And said unto them that sold doves, Take these things hence; make not my Father’s house an house of merchandise.* *And he said unto them, How is it that you sought me? wist you not that I must be about my Father’s business?* (Luke 2:49) At twelve, Yahusha (Jesus) says he must be *about my Father’s business*. Years later he calls the temple *my Father’s house*. It is the same Father, the same house, and the same one speaking. He is Elohim (God) and he has a Father, and both times he says so plainly.$n$,692,$n$*Wist ye not that I must be about my Father's business?* The twelve-year-old in the temple names the Father-Son relation that the Yochanan (John) 2 cleansing of the temple names — *make not my Father's house an house of merchandise.* The Formed-Son's first recorded words in Luke are the same Father-naming the Yochanan gospel returns to throughout.$n$,$n$John 2:16 — *make not my Father’s house an house of merchandise.* The house he guards in the temple is his Father's, the same Father whose business he said as a boy he must be about.$n$),
(6981,'canon','luke',3,38,$n$Which was the son of Enos, which was the son of Seth, which was the son of Adam, which was the son of Elohim (God).$n$,'canon','genesis',5,1,$n$thread:son-of-adam-as-judge-and-ladder | *Which was the son of Adam, which was the son of Elohim (God).* Luke's genealogy lands at the same Bereshit (Genesis) 5:1 toledot of Adam that names Adam as made in the likeness of Elohim. The Son-of-Adam-as-ladder substance is anchored here.$n$,$n$Genesis 5:1 — *This is the book of the generations of Adam. In the day that Elohim (God) created man, in the likeness of Elohim (God) made he him;* *Which was the son of Enos, which was the son of Seth, which was the son of Adam, which was the son of Elohim (God).* (Luke 3:38) Luke's line of fathers ends at Adam, and Genesis opens that line. *This is the book of the generations of Adam.* Adam was made in the likeness of Elohim (God), and Luke carries the line down through Seth and Enos. The Son of Adam is a name with a family behind it.$n$,692,$n$*Which was the son of Adam, which was the son of Elohim (God).* Luke's genealogy lands at the same Bereshit (Genesis) 5:1 toledot of Adam that names Adam as made in the likeness of Elohim. The Son-of-Adam-as-ladder substance is anchored here.$n$,$n$Genesis 5:1 — *In the day that Elohim (God) created man, in the likeness of Elohim (God) made he him.* Adam's book of generations begins with Adam made in the likeness of Elohim (God), and Luke's line runs down to the one called the Son of Adam.$n$),
(8205,'canon','john',1,51,$n$And he says unto him, Verily, verily, I say unto you, Hereafter you shall see heaven open, and the angels of Elohim (God) ascending and descending upon the Son of Adam.$n$,'canon','genesis',28,12,$n$thread:son-of-adam-as-judge-and-ladder | *And behold a ladder set up on the earth, and the top of it reached to heaven: and behold the angels of Elohim (God) ascending and descending on it* — Ya'aqov's (Jacob's) Bethel ladder is the architecture the *angels of Elohim (God) ascending and descending upon the Son of Adam* names as fulfilled on the body of the Formed one in flesh.$n$,$n$Genesis 28:12 — *And he dreamed, and behold a ladder set up on the earth, and the top of it reached to heaven: and behold the angels of Elohim (God) ascending and descending on it.* *And he says unto him, Verily, verily, I say unto you, Hereafter you shall see heaven open, and the angels of Elohim (God) ascending and descending upon the Son of Adam.* (John 1:51) Jacob saw a ladder with its top in heaven and *the angels of Elohim (God) ascending and descending* on it. Yahusha (Jesus) tells Nathanael they will see the same upon himself. He is the ladder, set on the earth with its top in heaven, and the flesh he stands in is Adam's line.$n$,692,$n$*And behold a ladder set up on the earth, and the top of it reached to heaven: and behold the angels of Elohim (God) ascending and descending on it* — Ya'aqov's (Jacob's) Bethel ladder is the architecture the *angels of Elohim (God) ascending and descending upon the Son of Adam* names as fulfilled on the body of the Formed one in flesh.$n$,$n$Genesis 28:12 — *a ladder set up on the earth, and the top of it reached to heaven.* The ladder at Bethel is what Yahusha (Jesus) says is now seen upon the Son of Adam.$n$),
(8204,'canon','john',1,51,$n$And he says unto him, Verily, verily, I say unto you, Hereafter you shall see heaven open, and the angels of Elohim (God) ascending and descending upon the Son of Adam.$n$,'canon','genesis',28,13,$n$thread:son-of-adam-as-judge-and-ladder | *And, behold, Yahuah (the LORD) stood above it* — Yahuah (the LORD) above the ladder; the Son of Adam at the bottom-and-top of the connection between heaven and earth. The Formless source above; the Formed expression as the ladder; the seed-of-Adam as the substance.$n$,$n$Genesis 28:13 — *And, behold, Yahuah (LORD) stood above it, and said, I am Yahuah Elohim (the LORD God) of Abraham thy father, and the Elohim (God) of Isaac: the land whereon thou liest, to thee will I give it, and to thy seed;* *And he says unto him, Verily, verily, I say unto you, Hereafter you shall see heaven open, and the angels of Elohim (God) ascending and descending upon the Son of Adam.* (John 1:51) Above the ladder stood Yahuah (LORD), and he gave Jacob the land and *to thy seed*. Yahusha (Jesus) says the angels go up and down upon the Son of Adam, so the one standing before Nathanael stands in that seed's flesh. The promise and the ladder meet in him.$n$,692,$n$*And, behold, Yahuah (the LORD) stood above it* — Yahuah (the LORD) above the ladder; the Son of Adam at the bottom-and-top of the connection between heaven and earth. The Formless source above; the Formed expression as the ladder; the seed-of-Adam as the substance.$n$,$n$Genesis 28:13 — *I am Yahuah Elohim (the LORD God) of Abraham thy father.* The one who stood above the ladder and spoke the promise to Jacob's seed is the one now standing in flesh before Nathanael.$n$),
(8196,'canon','john',5,27,$n$And has given him authority to execute judgment also, because he is the Son of Adam.$n$,'canon','psalms',8,4,$n$thread:son-of-adam-as-judge-and-ladder | *What is mortal man, that thou art mindful of him? and the son of Adam, that thou visitest him?* — the Psalm 8 *son of Adam* in the poetic-generic register; the verse Hebrews 2:6-8 cites of the Formed one's authority over the works of the Father's hands. The judgment-authority of John 5:27 sits in this same psalm-tradition.$n$,$n$Psalm 8:4 — *What is man, that thou art mindful of him? and the son of Adam, that thou visitest him?* *And has given him authority to execute judgment also, because he is the Son of Adam.* (John 5:27) The psalm asks what a son of Adam is that he should be visited, and goes on to dominion over the works of the hands of Elohim (God). John gives the answer a face. The authority to judge is given to Yahusha (Jesus) *because he is the Son of Adam*.$n$,692,$n$*What is mortal man, that thou art mindful of him? and the son of Adam, that thou visitest him?* — the Psalm 8 *son of Adam* in the poetic-generic register; the verse Hebrews 2:6-8 cites of the Formed one's authority over the works of the Father's hands. The judgment-authority of John 5:27 sits in this same psalm-tradition.$n$,$n$Psalm 8:4 — *and the son of Adam, that thou visitest him.* The psalm's son of Adam, visited and given dominion, is the Son of Adam to whom judgment is given in John.$n$),
(8203,'canon','john',5,27,$n$And has given him authority to execute judgment also, because he is the Son of Adam.$n$,'canon','daniel',7,13,$n$thread:son-of-adam-as-judge-and-ladder | *And behold, one like the Son of Adam came with the clouds of heaven, and came to the Ancient of Days, and they brought him near before him* — the *like the Son of Adam* of Daniel 7:13 receives the kingdom from the Ancient of Days; John 5:27 lands the judgment-authority on the same Son of Adam. The lineage-name and the judgment-authority hold together.$n$,$n$Daniel 7:13 — *I saw in the night visions, and, behold, one like the Son of Adam came with the clouds of heaven, and came to the Ancient of days, and they brought him near before him.* *And has given him authority to execute judgment also, because he is the Son of Adam.* (John 5:27) Daniel's page says *like*, and it stays *like* there. John's page says plainly that the authority to judge is given *because he is the Son of Adam*. Each speaks in its own words. Both have a giving, and both have the name.$n$,692,$n$*And behold, one like the Son of Adam came with the clouds of heaven, and came to the Ancient of Days, and they brought him near before him* — the *like the Son of Adam* of Daniel 7:13 receives the kingdom from the Ancient of Days; John 5:27 lands the judgment-authority on the same Son of Adam. The lineage-name and the judgment-authority hold together.$n$,$n$Daniel 7:13 — *one like the Son of Adam came with the clouds of heaven, and came to the Ancient of days.* Daniel sees one like the Son of Adam brought before the Ancient of days, and John says the judgment was given to the Son of Adam.$n$),
(8202,'canon','john',5,27,$n$And has given him authority to execute judgment also, because he is the Son of Adam.$n$,'canon','daniel',7,14,$n$thread:son-of-adam-as-judge-and-ladder | *And there was given him dominion, and glory, and a kingdom, that all people, nations, and languages, should serve him: his dominion is an everlasting dominion* — the everlasting-kingdom of the *kbar enash* is the dominion-credential of the judgment John 5:27 names. The lineage-name carries the kingdom.$n$,$n$Daniel 7:14 — *And there was given him dominion, and glory, and a kingdom, that all people, nations, and languages, should serve him: his dominion is an everlasting dominion, which shall not pass away, and his kingdom that which shall not be destroyed.* *And has given him authority to execute judgment also, because he is the Son of Adam.* (John 5:27) Both verses turn on a giving. John says the Father *hath given him authority*, and Daniel says dominion and a kingdom were given that all should serve him. Daniel's kingdom does not pass away. The judgment is part of what is handed to the Son of Adam, and the name is why.$n$,692,$n$*And there was given him dominion, and glory, and a kingdom, that all people, nations, and languages, should serve him: his dominion is an everlasting dominion* — the everlasting-kingdom of the *kbar enash* is the dominion-credential of the judgment John 5:27 names. The lineage-name carries the kingdom.$n$,$n$Daniel 7:14 — *his dominion is an everlasting dominion, which shall not pass away.* The dominion that never passes away is what stands behind the judgment given to the Son of Adam.$n$),
(8195,'canon','john',6,62,$n$What and if you shall see the Son of Adam ascend up where he was before?$n$,'canon','ezekiel',1,26,$n$thread:son-of-adam-as-judge-and-ladder | *And upon the likeness of the throne was the likeness as the appearance of a man above upon it* — the *likeness of a man* / *kbar enash* on the throne in Yechezkel's (Ezekiel's) vision; the Son of Adam who ascends up where he was before is the same throne-figure the prophets saw. The lineage-name and the throne-figure are one.$n$,$n$Ezekiel 1:26 — *And above the firmament that was over their heads was the likeness of a throne, as the appearance of a sapphire stone: and upon the likeness of the throne was the likeness as the appearance of a man above upon it.* *What and if you shall see the Son of Adam ascend up where he was before?* (John 6:62) Ezekiel sees *the likeness as the appearance of a man* upon the throne. Yahusha (Jesus) asks what they will do when they see the Son of Adam ascend *where he was before*. Ezekiel says likeness and appearance, and Yahusha (Jesus) says where he was. The one who goes up goes back to a place he had.$n$,692,$n$*And upon the likeness of the throne was the likeness as the appearance of a man above upon it* — the *likeness of a man* / *kbar enash* on the throne in Yechezkel's (Ezekiel's) vision; the Son of Adam who ascends up where he was before is the same throne-figure the prophets saw. The lineage-name and the throne-figure are one.$n$,$n$Ezekiel 1:26 — *upon the likeness of the throne was the likeness as the appearance of a man above upon it.* The prophet saw the likeness of a man above the throne, and the Son of Adam says he goes up to where he was before.$n$),
(8199,'canon','john',12,23,$n$And Yahusha (Jesus) answered them, saying, The hour is come, that the Son of Adam should be glorified.$n$,'canon','isaiah',52,13,$n$thread:son-of-adam-as-judge-and-ladder | *The hour is come, that the Son of Adam should be glorified* read with *Behold, my servant shall deal prudently, he shall be exalted and extolled, and be very high* — the suffering-servant's exaltation is the Son of Adam's glorification at the hour. The lineage-name and the suffering-servant carry the same substance.$n$,$n$Isaiah 52:13 — *Behold, my servant shall deal prudently, he shall be exalted and extolled, and be very high.* *And Yahusha (Jesus) answered them, saying, The hour is come, that the Son of Adam should be glorified.* (John 12:23) Isaiah's servant *shall be exalted and extolled*. Yahusha (Jesus) says the hour has come for the Son of Adam to be glorified, and the glory is that lifting. The same chapter goes on to the marring of his face, so the height comes by the road of the cross.$n$,692,$n$*The hour is come, that the Son of Adam should be glorified* read with *Behold, my servant shall deal prudently, he shall be exalted and extolled, and be very high* — the suffering-servant's exaltation is the Son of Adam's glorification at the hour. The lineage-name and the suffering-servant carry the same substance.$n$,$n$Isaiah 52:13 — *he shall be exalted and extolled, and be very high.* The servant who is exalted and made very high is the Son of Adam glorified when his hour comes.$n$),
(8198,'canon','john',12,34,$n$The people answered him, We have heard out of the law that Messiah (Christ) abides for ever: and how say you, The Son of Adam must be lifted up? who is this Son of Adam?$n$,'canon','psalms',110,1,$n$thread:son-of-adam-as-judge-and-ladder | *Who is this Son of Adam?* — the crowd cannot reconcile the *lifted up* with their expectation of a Messiah who *abideth for ever*; Psalm 110:1's *sit thou at my right hand, until I make thine enemies thy footstool* answers the question in the same psalm-tradition Yahusha (Jesus) himself cites at Matthew 22:44. The Son of Adam reigns; the lifting-up is the means.$n$,$n$Psalm 110:1 — *Yahuah (LORD) said unto my Lord, Sit thou at my right hand, until I make thine enemies thy footstool.* *The people answered him, We have heard out of the law that Messiah (Christ) abides for ever: and how say you, The Son of Adam must be lifted up? who is this Son of Adam?* (John 12:34) The crowd asks *who is this Son of Adam?* They heard from the law that Messiah (Christ) abides for ever, yet the Son of Adam must be lifted up. The psalm has Yahuah (LORD) tell the one at his right hand to sit until his enemies are a footstool. The lifting is the road to that sitting.$n$,692,$n$*Who is this Son of Adam?* — the crowd cannot reconcile the *lifted up* with their expectation of a Messiah who *abideth for ever*; Psalm 110:1's *sit thou at my right hand, until I make thine enemies thy footstool* answers the question in the same psalm-tradition Yahusha (Jesus) himself cites at Matthew 22:44. The Son of Adam reigns; the lifting-up is the means.$n$,$n$Psalm 110:1 — *Sit thou at my right hand, until I make thine enemies thy footstool.* The one lifted up is the one set at the right hand until his enemies are made his footstool, so the lifting leads to reigning.$n$),
(8197,'canon','john',13,31,$n$Therefore, when he was gone out, Yahusha (Jesus) said, Now is the Son of Adam glorified, and Elohim (God) is glorified in him.$n$,'canon','daniel',7,14,$n$thread:son-of-adam-as-judge-and-ladder | *Now is the Son of Adam glorified, and Elohim (God) is glorified in him* — the glorification at the hour the Son of Adam goes to the cross is the same glorification of Daniel 7:14's *given him dominion, and glory.* The hour and the kingdom-transfer are named together; the lineage-name and the glory hold.$n$,$n$Daniel 7:14 — *And there was given him dominion, and glory, and a kingdom, that all people, nations, and languages, should serve him: his dominion is an everlasting dominion, which shall not pass away, and his kingdom that which shall not be destroyed.* *Therefore, when he was gone out, Yahusha (Jesus) said, Now is the Son of Adam glorified, and Elohim (God) is glorified in him.* (John 13:31) Judas has gone out, and Yahusha (Jesus) says the Son of Adam is glorified and Elohim (God) is glorified in him. Daniel saw one like the Son of Adam given *dominion, and glory, and a kingdom*. The glory said at that table is the glory given there, and the Father is honoured in the Son, not set aside.$n$,692,$n$*Now is the Son of Adam glorified, and Elohim (God) is glorified in him* — the glorification at the hour the Son of Adam goes to the cross is the same glorification of Daniel 7:14's *given him dominion, and glory.* The hour and the kingdom-transfer are named together; the lineage-name and the glory hold.$n$,$n$Daniel 7:14 — *his dominion is an everlasting dominion, which shall not pass away.* The glory named at the hour is the glory given with the everlasting dominion in Daniel.$n$);
CREATE TEMP TABLE s503c_thread (id bigint, slug text, old_title text, new_title text, old_summary text, new_summary text) ON COMMIT DROP;
INSERT INTO s503c_thread VALUES (692, 'son-of-adam-as-judge-and-ladder', $n$Son of Adam — the lineage-name as ladder, judgment, and ascent$n$, $n$The Son of Adam — the seed's own name: the ladder at Bethel, the judgment given to him, the ransom, and the going up (Genesis 28; Daniel 7; Psalm 8; Mark 10; John 1)$n$, $n$John uses the *Son of Adam* title across his gospel in a register the other gospels do not match. He opens with the title at John 1:51 — *ye shall see heaven open, and the angels of Elohim (God) ascending and descending upon the Son of Adam.* He returns to the title at John 5:27 as the judgment-credential: *the Father hath given him authority to execute judgment also, because he is the Son of Adam.* He lands the title in John 6 as the substance the bread-from-heaven discourse rests on (6:53, 6:62), in John 12 as the lifted-up substance (12:23, 12:34), and in John 13 as the glorified one at the hour (13:31). The framework's seed-of-Adam restoration of the title is load-bearing through all of these — the *son of Adam* names the lineage on which the framework's whole architecture rests.

*And he saith unto him, Verily, verily, I say unto you, Hereafter ye shall see heaven open, and the angels of Elohim (God) ascending and descending upon the Son of Adam.* (John 1:51)

*And hath given him authority to execute judgment also, because he is the Son of Adam.* (John 5:27)

*And he dreamed, and behold a ladder set up on the earth, and the top of it reached to heaven: and behold the angels of Elohim (God) ascending and descending on it. And, behold, Yahuah (the LORD) stood above it.* (Genesis 28:12-13)

The ladder of Ya'aqov's (Jacob's) Bethel vision is the architecture John 1:51 names as fulfilled on the Formed one in flesh. The angels ascending and descending on the ladder ascend and descend on the Son of Adam — the body of the Formed one is the connection between heaven and earth that Ya'aqov (Jacob) saw in the dream. The lineage-name carries the substance: the Son of Adam is the seed of Adam through whom the heaven-earth connection is reopened, the ladder Ya'aqov (Jacob) saw is the body of the lineage taking on the office it always pointed toward.

The judgment-credential at John 5:27 carries the same lineage-weight. *Because he is the Son of Adam* — because he is of the seed, the judgment of the seed's covenant is his to execute. Daniel 7:13's *one like the Son of Adam* receives the everlasting kingdom from the Ancient of Days; the kaph-comparative honors the incarnation truth that the figure resembles mortal-man because he took on flesh, while remaining the Formed cloud-rider. John 5:27 lands the judgment-authority on the same Son of Adam whose body is the ladder, whose flesh is the bread, whose lifting-up is the gathering-ensign.

The eating-the-flesh discourse of John 6:53-58 names the lineage-name as the food the gathered take in. *Except ye eat the flesh of the Son of Adam, and drink his blood, ye have no life in you* — the seed-of-Adam is the substance the new birth incorporates; the body of the lineage becomes the food of the gathered body. John 6:62 returns to the title in the ascent: *what and if ye shall see the Son of Adam ascend up where he was before?* The pre-existent Formed one who descended is the same Son of Adam who ascends; the lineage-name is preserved through the descent, the incarnation, the death, the resurrection, and the ascent.

John 12:23 names the hour: *the hour is come, that the Son of Adam should be glorified.* John 12:34 records the crowd's question — *who is this Son of Adam?* — the title puzzles the hearers because the inherited reading had emptied the title of its lineage-weight; the Formed one carries it back to its Tanakh substance. John 13:31 lands the glorification at the table after Yehuda (Judas) goes out: *now is the Son of Adam glorified, and Elohim (God) is glorified in him.* The lineage-name is the throughline.$n$, $n$It ain't new. The name Yahusha (Jesus) uses for himself more than any other, the Son of Adam, has a lineage in it. Adam's book of generations runs straight down to Luke's:

*This is the book of the generations of Adam. In the day that Elohim (God) created man, in the likeness of Elohim (God) made he him;* (Genesis 5:1)

*Which was the son of Enos, which was the son of Seth, which was the son of Adam, which was the son of Elohim (God).* (Luke 3:38)

John opens the name with Jacob's ladder:

*And he saith unto him, Verily, verily, I say unto you, Hereafter ye shall see heaven open, and the angels of Elohim (God) ascending and descending upon the Son of Adam.* (John 1:51)

*And he dreamed, and behold a ladder set up on the earth, and the top of it reached to heaven: and behold the angels of Elohim (God) ascending and descending on it.* (Genesis 28:12)

*And, behold, Yahuah (LORD) stood above it, and said, I am Yahuah Elohim (the LORD God) of Abraham thy father, and the Elohim (God) of Isaac: the land whereon thou liest, to thee will I give it, and to thy seed;* (Genesis 28:13)

What Jacob saw set up on the earth with its top in heaven, the angels going up and down on it, Yahusha (Jesus) says they will see upon himself. He is the ladder. The one who stood above it and spoke the promise to Jacob's seed is the one now standing in front of Nathanael in flesh, and the flesh he stands in is that seed. The name carries the judgment too, and the reason given is the name itself:

*And hath given him authority to execute judgment also, because he is the Son of Adam.* (John 5:27)

Daniel had seen one like him brought before the Ancient of days and given the kingdom. Daniel says *like*, and it stays *like* on his page; what is given there is the kingdom that does not pass:

*I saw in the night visions, and, behold, one like the Son of Adam came with the clouds of heaven, and came to the Ancient of days, and they brought him near before him.* (Daniel 7:13)

*And there was given him dominion, and glory, and a kingdom, that all people, nations, and languages, should serve him: his dominion is an everlasting dominion, which shall not pass away, and his kingdom that which shall not be destroyed.* (Daniel 7:14)

The psalm asks what the son of Adam is that he should be visited at all, and answers with dominion:

*What is man, that thou art mindful of him? and the son of Adam, that thou visitest him?* (Psalm 8:4)

*Thou madest him to have dominion over the works of thy hands; thou hast put all things under his feet:* (Psalm 8:6)

Mark has the name at the forgiving of sins, at the sabbath, at the suffering, and at the ransom:

*But that ye may know that the Son of Adam hath power on earth to forgive sins, (he saith to the sick of the palsy,)* (Mark 2:10)

*Therefore the Son of Adam is Adonai (Lord) also of the sabbath.* (Mark 2:28)

*And he began to teach them, that the Son of Adam must suffer many things, and be rejected of the elders, and of the chief priests, and scribes, and be killed, and after three days rise again.* (Mark 8:31)

*For even the Son of Adam came not to be ministered unto, but to minister, and to give his life a ransom for many.* (Mark 10:45)

Being master of the sabbath is not the sabbath put away; it is the one who made the day saying whose it is. And the ransom is the servant Isaiah saw bearing the iniquities of the many:

*He shall see of the travail of his soul, and shall be satisfied: by his knowledge shall my righteous servant justify many; for he shall bear their iniquities.* (Isaiah 53:11)

Hebrews says why the name is a seed-name and not a title any man could wear:

*For verily he took not on him the nature of angels; but he took on him the seed of Abraham.* (Hebrews 2:16)

Ezekiel saw a man's likeness on the throne above the firmament long before the Son of Adam said where he had been before:

*And above the firmament that was over their heads was the likeness of a throne, as the appearance of a sapphire stone: and upon the likeness of the throne was the likeness as the appearance of a man above upon it.* (Ezekiel 1:26)

*And no man hath ascended up to heaven, but he that came down from heaven, even the Son of Adam which is in heaven.* (John 3:13)

*What and if ye shall see the Son of Adam ascend up where he was before?* (John 6:62)

*Therefore, when he was gone out, Yahusha (Jesus) said, Now is the Son of Adam glorified, and Elohim (God) is glorified in him.* (John 13:31)

The one who came down took Adam's line in the flesh, and the one who goes up is the same, and the name goes with him both ways. The ladder, the judgment, the ransom and the glory all hang on one word the translators flattened to *man*: Adam.$n$);

DO $s503c$
DECLARE r record; x record; n int;
BEGIN
  FOR r IN SELECT * FROM s503c_cards LOOP
    SELECT xr.id, xr.note, sv.text AS stext, se.slug AS sed, sb.slug AS sbook, sc.chapter_number AS sch, sv.verse_number AS svn, te.slug AS ted, tb.slug AS tbook, tc.chapter_number AS tch, tv.verse_number AS tvn
      INTO x FROM cross_references xr
      JOIN verses sv ON sv.id = xr.source_verse_id JOIN chapters sc ON sc.id = sv.chapter_id JOIN books sb ON sb.id = sc.book_id JOIN editions se ON se.id = sb.edition_id
      JOIN verses tv ON tv.id = xr.target_verse_id JOIN chapters tc ON tc.id = tv.chapter_id JOIN books tb ON tb.id = tc.book_id JOIN editions te ON te.id = tb.edition_id
      WHERE xr.id = r.id;
    IF NOT FOUND THEN RAISE EXCEPTION 'S503c: card % is gone', r.id; END IF;
    IF x.sed <> r.s_ed OR x.sbook <> r.s_book OR x.sch <> r.src_ch OR x.svn <> r.src_vn OR x.ted <> r.t_ed OR x.tbook <> r.tgt_book OR x.tch <> r.tgt_ch OR x.tvn <> r.tgt_vn THEN
      RAISE EXCEPTION 'S503c: card % no longer sits on the verse pair this was written for', r.id; END IF;
    IF x.stext <> r.src_text THEN RAISE EXCEPTION 'S503c: live text of % %:% differs from the read-back — re-dump and rebuild', r.s_book, r.src_ch, r.src_vn; END IF;
    IF x.note IS DISTINCT FROM r.old_note AND x.note IS DISTINCT FROM r.new_note THEN RAISE EXCEPTION 'S503c: the live note of card % differs from the read-back — re-dump and rebuild', r.id; END IF;
    SELECT count(*) INTO n FROM cross_reference_thread_members m WHERE m.cross_reference_id = r.id AND m.thread_id = r.thread_id AND (m.member_note IS NOT DISTINCT FROM r.old_mnote OR m.member_note IS NOT DISTINCT FROM r.new_mnote);
    IF n <> 1 THEN RAISE EXCEPTION 'S503c: card % has no member row in thread % carrying the member note this was written against', r.id, r.thread_id; END IF;
  END LOOP;
  SELECT t.* INTO x FROM cross_reference_threads t JOIN s503c_thread s ON s.id = t.id AND s.slug = t.slug;
  IF NOT FOUND THEN RAISE EXCEPTION 'S503c: thread 692 not found under its slug'; END IF;
  SELECT count(*) INTO n FROM cross_reference_threads t JOIN s503c_thread s ON s.id = t.id
    WHERE (t.title = s.old_title AND t.summary_md = s.old_summary) OR (t.title = s.new_title AND t.summary_md = s.new_summary);
  IF n <> 1 THEN RAISE EXCEPTION 'S503c: thread 692 title/summary differ from the read-back — re-dump and rebuild'; END IF;
END $s503c$;

DO $s503c2$
DECLARE n_notes int; n_m int; n_t int; n_c int;
BEGIN
  SELECT count(*) INTO n_c FROM s503c_cards;
  UPDATE cross_references xr SET note = c.new_note FROM s503c_cards c WHERE xr.id = c.id AND xr.note IS NOT DISTINCT FROM c.old_note AND c.old_note IS DISTINCT FROM c.new_note;
  GET DIAGNOSTICS n_notes = ROW_COUNT;
  UPDATE cross_reference_thread_members m SET member_note = c.new_mnote FROM s503c_cards c WHERE m.cross_reference_id = c.id AND m.thread_id = c.thread_id AND m.member_note IS NOT DISTINCT FROM c.old_mnote AND c.old_mnote IS DISTINCT FROM c.new_mnote;
  GET DIAGNOSTICS n_m = ROW_COUNT;
  UPDATE cross_reference_threads t SET title = s.new_title, summary_md = s.new_summary FROM s503c_thread s WHERE t.id = s.id AND t.title = s.old_title AND t.summary_md = s.old_summary AND (s.old_title <> s.new_title OR s.old_summary <> s.new_summary);
  GET DIAGNOSTICS n_t = ROW_COUNT;
  RAISE NOTICE 'S503c (son-of-adam-as) summary: notes rewritten % / already there %; member notes rewritten % / already there %; thread rewritten % / already there %', n_notes, n_c - n_notes, n_m, n_c - n_m, n_t, 1 - n_t;
END $s503c2$;
COMMIT;
\echo 'session503c — son-of-adam-as done.'
